"""Compile the pinned upstream app-server for Android/Bionic, preserving Android's sandbox."""
import argparse,json,os,pathlib,subprocess,hashlib,shutil,tomllib
p=argparse.ArgumentParser();p.add_argument('--source',required=True);p.add_argument('--ndk',required=True);p.add_argument('--target',choices=['x86_64-linux-android','aarch64-linux-android'],required=True);p.add_argument('--output',required=True);a=p.parse_args();source=pathlib.Path(a.source).resolve();root=pathlib.Path(__file__).resolve().parent.parent;manifest=json.loads((root/'android/codex-source.json').read_text());ndk=pathlib.Path(a.ndk).resolve();tool=ndk/'toolchains/llvm/prebuilt/linux-x86_64/bin';project=source/'codex-rs'
sha=subprocess.check_output(['git','rev-parse','HEAD'],cwd=source,text=True).strip();assert sha==manifest['commit'],'Upstream source differs from the locked commit'
# mxc-sdk has no Android engine; this dependency is only used by supported desktop targets.
mxc=project/'mxc-sandbox/Cargo.toml';text=mxc.read_text();anchor='mxc-sdk = { workspace = true }';assert text.count(anchor)==1;text=text.replace(anchor,'');text+='\n[target.\'cfg(not(target_os = "android"))\'.dependencies]\nmxc-sdk = { workspace = true }\n';mxc.write_text(text)
# Android does not provide an OpenSSL SDK. Build the already locked upstream OpenSSL source.
core=project/'core/Cargo.toml';text=core.read_text();text+='\n[target.\'cfg(target_os = "android")\'.dependencies]\nopenssl-sys = { workspace = true, features = ["vendored"] }\n';core.write_text(text)
env=os.environ.copy();target=a.target;clang=tool/(target+str(manifest['minApi'])+'-clang');cxx=tool/(target+str(manifest['minApi'])+'-clang++');normalized=target.replace('-','_');env.update({'ANDROID_NDK_HOME':str(ndk),'ANDROID_NDK_ROOT':str(ndk),'PKG_CONFIG_ALLOW_CROSS':'1','OPENSSL_NO_PKG_CONFIG':'1','OPENSSL_STATIC':'1','LIBLZMA_NO_PKG_CONFIG':'1','CODEX_SKIP_VENDORED_BWRAP':'1','CARGO_BUILD_JOBS':'2','CARGO_INCREMENTAL':'0','CARGO_PROFILE_RELEASE_LTO':'false','CARGO_PROFILE_RELEASE_CODEGEN_UNITS':'16','CARGO_PROFILE_RELEASE_STRIP':'symbols','CARGO_TARGET_'+normalized.upper()+'_LINKER':str(clang),'CARGO_TARGET_'+normalized.upper()+'_RUSTFLAGS':'-C link-arg=-Wl,-z,max-page-size=16384 -C link-arg=-lc++_shared','BINDGEN_EXTRA_CLANG_ARGS':'--target='+target+str(manifest['minApi'])+' --sysroot='+str(tool.parent/'sysroot')})
for suffix in [target,normalized]:env['CC_'+suffix]=str(clang);env['CXX_'+suffix]=str(cxx);env['AR_'+suffix]=str(tool/'llvm-ar')
env['PATH']=str(tool)+os.pathsep+env.get('PATH','')
lock_file=project/'Cargo.lock';original_lock=tomllib.loads(lock_file.read_text());identity=lambda q:(q['name'],q['version'],q.get('source'),q.get('checksum'));locked={identity(q) for q in original_lock['package'] if q.get('source')}
# Refresh only workspace edges introduced above. Existing third-party versions remain fixed.
subprocess.run(['cargo','update','--workspace'],cwd=project,env=env,check=True)
updated=tomllib.loads(lock_file.read_text());added={identity(q) for q in updated['package'] if q.get('source')}-locked
assert not added,'Android compatibility resolution changed third-party package identities: '+repr(sorted(added))
subprocess.run(['cargo','build','--locked','--release','--target',target,'-p','codex-app-server','--bin','codex-app-server'],cwd=project,env=env,check=True)
output=pathlib.Path(a.output);output.mkdir(parents=True,exist_ok=True);binary=project/'target'/target/'release/codex-app-server';subprocess.run([str(tool/'llvm-strip'),'--strip-debug',str(binary)],check=True);dest=output/'libhoutu_codex.so';shutil.copyfile(binary,dest);report={**manifest,'target':target,'sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'bytes':dest.stat().st_size,'nativeAndroid':True,'lockSha256':hashlib.sha256(lock_file.read_bytes()).hexdigest(),'thirdPartyIdentityChanges':0};(output/'build.json').write_text(json.dumps(report,indent=2)+'\n');(output/'platform.patch').write_text(subprocess.check_output(['git','diff','--','codex-rs/mxc-sandbox/Cargo.toml','codex-rs/core/Cargo.toml','codex-rs/Cargo.lock'],cwd=source,text=True));shutil.copyfile(lock_file,output/'Cargo.lock');shutil.copyfile(source/'LICENSE',output/'LICENSE');shutil.copyfile(source/'NOTICE',output/'NOTICE');print(json.dumps(report))
